// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address owner = address(this);
        address eoa = address(0x1);

        vm.deal(owner, 2 ether);
        vm.prank(owner);
        c.sendMoney(eoa, 1 ether, "");

        vm.deal(owner, 1 ether);
        vm.prank(owner);
        (bool success, ) = address(c).call{value: 1 ether}("");

        assertTrue(success == true && c.depositsCount() == 1);
    }
}
